124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
127	        HttpHeaders headers = new HttpHeaders();
128	        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
129	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
130	        if (existingId != null) {
131	            Owner existing = this.clinicService.findOwnerById(existingId);
132	            if (existing != null) {
133	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
134	            }
135	        }
136	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
137	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
138	        owner.setTelephone(normalizedTelephone);
139	        owner.setEmail(normalizeEmail(owner.getEmail()));
140	        applyAddress(owner);
141	        validatePostcode(owner.getCity(), owner.getPostcode());
142	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
143	        if (effectiveRegistrationDate == null) {
144	            effectiveRegistrationDate = LocalDate.now();
145	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
146	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
147	                "registrationDate must not be later than the current server date");
148	        }
149	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
150	        owner.setRegistrationDate(effectiveRegistrationDate);
151	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
152	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
153	                "the maximum number of owners that may be created today has been reached");
154	        }
155	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
156	        // The household id is deterministic (derived from the last name and postcode), so every
157	        // owner is keyed to its household automatically, regardless of creation order.
158	        this.clinicService.assignHousehold(owner);
159	        // An owner joining an existing household is now admitted rather than rejected; their
160	        // membership level is instead capped relative to the household (see the level-ceiling rule
161	        // applied via the membershipLevelCap below).
162	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
163	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
164	            throw new ResponseStatusException(HttpStatus.CONFLICT,
165	                "an owner with the same identity already exists");
166	        }
167	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
168	            throw new ResponseStatusException(HttpStatus.CONFLICT,
169	                "city has reached its maximum number of owners");
170	        }
171	        owner.setCustomerCode(customerCodeFor(owner));
172	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
173	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
174	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
175	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
176	        owner.setBulkSignupWarning(
177	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
178	        // A declared household member (one created with 'sharesHousehold' that joins an existing
179	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
180	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
181	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
182	        owner.setPossibleDuplicate(softDuplicate != null);
183	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
184	        this.clinicService.saveOwner(owner);
185	        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
188	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
189	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
190	        headers.setLocation(UriComponentsBuilder.newInstance()
191	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
192	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
193	    }
