291	
292	    /**
293	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
294	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
295	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
296	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
297	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
298	     * sequence number, so its base form is a stable function of the owner's region and
299	     * telephone/last-name identity rather than of creation order.
300	     *
301	     * <p>When that computed code already belongs to an existing owner it is de-duplicated by
302	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a code no
303	     * existing owner already has; the de-duplicated code is returned.
304	     *
305	     * @param owner the owner being created, with its telephone already normalized to E.164 form
306	     * @return the assigned, collision-free customer code
307	     */
308	    private String customerCodeFor(Owner owner) {
309	        String region = ownerMapper.regionOf(owner);
310	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
311	            .substring(0, 8);
312	        String baseCode = region + "-" + hash8;
313	        if (!isCustomerCodeInUse(baseCode)) {
314	            return baseCode;
315	        }
316	        int n = 2;
317	        String candidate = baseCode + "-" + n;
318	        while (isCustomerCodeInUse(candidate)) {
319	            n++;
320	            candidate = baseCode + "-" + n;
321	        }
322	        return candidate;
323	    }
324	
325	    /**
326	     * Determines whether any existing owner already carries the given {@code customerCode}, compared
327	     * exactly. Called while assigning a new owner's code so collisions can be de-duplicated.
328	     *
329	     * @param customerCode the candidate customer code to look for
330	     * @return {@code true} if an existing owner already has that customer code
331	     */
332	    private boolean isCustomerCodeInUse(String customerCode) {
333	        for (Owner existing : this.clinicService.findAllOwners()) {
334	            if (customerCode.equals(existing.getCustomerCode())) {
335	                return true;
336	            }
337	        }
338	        return false;
339	    }
340	
341	    /**
342	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
343	     * owner's city already contains this many owners.
344	     */
345	    private static final int CITY_CAPACITY = 50;
346	
347	    /**
348	     * The maximum number of owners that may be created on a single day. A create is rejected with
349	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
350	     * {@code registrationDate}.
351	     */
352	    private static final int DAILY_CREATE_LIMIT = 100;
353	
354	    /**
355	     * The number of owners that must already have been created for the current day before a new
356	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
357	     * owners already carry today's {@code registrationDate}.
358	     */
359	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
360	
361	    /**
362	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
363	     * of these dates is rolled forward, exactly as it is for a weekend day.
364	     */
365	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
366	        LocalDate.parse("2026-01-01"),
367	        LocalDate.parse("2026-01-26"),
368	        LocalDate.parse("2026-04-25"),
369	        LocalDate.parse("2026-12-25"),
370	        LocalDate.parse("2026-12-28"));
371	
372	    /**
373	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
374	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
375	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
376	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
377	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
378	     * falls on a business day.
379	     *
380	     * @param date the effective registration date
381	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
382	     */
383	    private static LocalDate rollToBusinessDay(LocalDate date) {
384	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
385	            date = date.plusDays(1);
386	        }
387	        return date;
388	    }
389	
390	    private static boolean isWeekend(LocalDate date) {
391	        return switch (date.getDayOfWeek()) {
392	            case SATURDAY, SUNDAY -> true;
393	            default -> false;
394	        };
395	    }
396	
397	    /**
398	     * Counts the existing owners whose {@code registrationDate} equals the given (already
399	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
400	     * business day. Called before a new owner is saved, so the returned value reflects the number of
401	     * owners created for that day prior to this create.
402	     *
403	     * @param date the adjusted business-day registration date to count against
404	     * @return the number of existing owners registered on that date
405	     */
406	    private int countOwnersRegisteredOn(LocalDate date) {
407	        return (int) this.clinicService.findAllOwners().stream()
408	            .filter(existing -> date.equals(existing.getRegistrationDate()))
409	            .count();
410	    }
411	
412	    /**
413	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
414	     *
415	     * @param city the city to count owners for
416	     * @return the number of existing owners in that city
417	     */
418	    private int countOwnersInCity(String city) {
419	        return (int) this.clinicService.findAllOwners().stream()
420	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
421	            .count();
422	    }
423	
424	    /**
425	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
426	     * the last two digits of the fiscal year (which starts on 1 July) of the business-day-adjusted
427	     * registration date (e.g. {@code 'NSW-1A2B3C4D-M27'}). The fiscal year is derived via
428	     * {@link OwnerMapper#fiscalYear(LocalDate)}, the single source of truth also used by the DTO's
429	     * {@code fiscalYear} field.
430	     *
431	     * @param customerCode     the owner's assigned customer code
432	     * @param registrationDate the owner's business-day-adjusted registration date
433	     * @return the assigned membership number
434	     */
435	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
436	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
437	        return String.format("%s-M%s", customerCode, yy);
438	    }
439	
440	    /**
441	     * Counts the existing owners that already share the given first name and last name, comparing
442	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
443	     * the number of namesakes that existed prior to this create.
444	     *
445	     * @param firstName the new owner's first name
446	     * @param lastName  the new owner's last name
447	     * @return the number of existing owners with the same first and last name
448	     */
449	    private int countNamesakes(String firstName, String lastName) {
450	        int count = 0;
451	        for (Owner existing : this.clinicService.findAllOwners()) {
452	            if (firstName.equalsIgnoreCase(existing.getFirstName())
453	                && lastName.equalsIgnoreCase(existing.getLastName())) {
454	                count++;
455	            }
456	        }
457	        return count;
458	    }
459	
460	    /**
461	     * Counts the existing owners that already belong to the given household (i.e. that share the
462	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
463	     * being created yields the household's total size at the moment of creation. Owners without a
464	     * household id are ignored.
465	     *
466	     * @param householdId the new owner's assigned household id
467	     * @return the number of existing owners already in that household
468	     */
469	    private int countHouseholdMembers(String householdId) {
470	        if (householdId == null) {
471	            return 0;
472	        }
473	        int count = 0;
474	        for (Owner existing : this.clinicService.findAllOwners()) {
475	            if (householdId.equals(existing.getHouseholdId())) {
476	                count++;
477	            }
478	        }
479	        return count;
480	    }
481	
482	    /**
483	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
484	     * current maximum effective membership level among the existing owners in that household. The
485	     * ceiling is frozen on the owner at creation and later applied by
486	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
487	     * existing member (or the owner has no household id), meaning no cap applies.
488	     *
489	     * @param householdId the new owner's assigned household id
490	     * @return one above the household's current maximum membership level, or {@code null} when the
491	     *         household has no existing member
492	     */
493	    private Integer householdMembershipLevelCap(String householdId) {
494	        if (householdId == null) {
495	            return null;
496	        }
497	        Integer maxLevel = null;
498	        for (Owner existing : this.clinicService.findAllOwners()) {
499	            if (householdId.equals(existing.getHouseholdId())) {
500	                int level = ownerMapper.toMembershipLevel(existing);
501	                if (maxLevel == null || level > maxLevel) {
502	                    maxLevel = level;
503	                }
504	            }
505	        }
506	        return maxLevel == null ? null : maxLevel + 1;
507	    }
508	
509	    /**
510	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
511	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
512	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
513	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
514	     * string is what gets stored and returned.
515	     *
516	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
517	     *
518	     * <p>Once in E.164 form the national-number length is validated against the country code: a
519	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
520	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
521	     * rule are accepted on the general 8-to-15 digit length alone.
522	     *
523	     * @param telephone the raw telephone value supplied by the client
524	     * @return the normalized E.164 telephone number
525	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
526	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
527	     *                                 after the {@code '+'}, or the wrong national-number length for
528	     *                                 its country code)
529	     */
530	    private static String normalizeTelephone(String telephone) {
531	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
532	        String digits;
533	        if (cleaned.startsWith("+")) {
534	            digits = cleaned.substring(1);
535	        } else {
536	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
537	            digits = "61" + national;
538	        }
539	        if (!digits.matches("[0-9]{8,15}")) {
540	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
541	                "telephone could not be normalized to a valid E.164 number");
542	        }
543	        validateNationalNumberLength(digits);
544	        return "+" + digits;
545	    }
546	
547	    /**
548	     * Validates the national-number length of an E.164 number (its digits, without the leading
549	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
550	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
551	     * (only the general 8-to-15 digit rule applies).
552	     *
553	     * @param digits the E.164 digits without the leading {@code '+'}
554	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
555	     *                                 digits does not match the country code's required length
556	     */
557	    private static void validateNationalNumberLength(String digits) {
558	        E164PhoneNumbers.countryCode(digits)
559	            .ifPresent(code -> {
560	                int nationalLength = digits.length() - code.length();
561	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
562	                if (nationalLength != required) {
563	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
564	                        "telephone must have " + required
565	                            + " national digits for country code +" + code);
566	                }
567	            });
568	    }
569	
570	    /**
571	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
572	     * containing at least one dot, none of the three sections containing whitespace or an
573	     * additional {@code @}.
574	     */
575	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
576	
577	    /**
578	     * Disposable email domains that are not accepted for an owner. An email whose domain is on this
579	     * blocklist is rejected with {@link HttpStatus#BAD_REQUEST}. Entries are lower-case and matched
580	     * case-insensitively against the domain (the part after the {@code @}).
581	     */
582	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
583	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
584	
585	    /**
586	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
587	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
588	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
589	     * lower-cased.
590	     *
591	     * @param email the raw email value supplied by the client, possibly {@code null}
592	     * @return the lower-cased email, or {@code null} when none was supplied
593	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
594	     *                                 is not a syntactically valid address, or its domain is on the
595	     *                                 disposable-domain blocklist
596	     */
597	    private static String normalizeEmail(String email) {
598	        if (email == null) {
599	            return null;
600	        }
601	        if (!EMAIL_PATTERN.matcher(email).matches()) {
602	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
603	                "email must be a syntactically valid address");
604	        }
605	        String normalized = email.toLowerCase(Locale.ROOT);
606	        String domain = normalized.substring(normalized.indexOf('@') + 1);
607	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
608	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
609	                "email domain " + domain + " is not allowed");
610	        }
611	        return normalized;
612	    }
613	
614	    /**
615	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
616	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
617	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
618	     */
619	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
620	        "NSW", new int[] {2000, 2099},
621	        "VIC", new int[] {3000, 3099},
622	        "QLD", new int[] {4000, 4099});
623	
624	    /**
625	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
626	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
627	     * four-digit format is enforced by request validation; here the value is range-checked: when the
628	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
629	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
630	     * accepts any four-digit postcode.
631	     *
632	     * @param city     the owner's city
633	     * @param postcode the owner's postcode, possibly {@code null}
634	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
635	     *                                 out of range for the city's region
636	     */
637	    private static void validatePostcode(String city, String postcode) {
638	        if (postcode == null) {
639	            return;
640	        }
641	        String region = OwnerMapper.CITY_REGION.get(city);
642	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
643	        if (range == null) {
644	            return;
645	        }
646	        int value = Integer.parseInt(postcode);
647	        if (value < range[0] || value > range[1]) {
648	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
649	                "postcode " + postcode + " is not valid for region " + region);
650	        }
651	    }
652	
653	    /**
654	     * Common street-type abbreviations expanded to their full word during address normalization.
655	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
656	     */
657	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
658	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
659	
660	    /**
661	     * Applies an owner's address, accepting either the structured form (a non-blank
662	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
663	     * preferring the structured fields when present. Whichever fields are supplied are normalized
664	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
665	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
666	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
667	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
668	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
669	     * {@code address} (plus city) is still accepted.
670	     *
671	     * @param owner the owner being created or updated, carrying the raw address fields
672	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
673	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
674	     *                                 supplied
675	     */
676	    private static void applyAddress(Owner owner) {
677	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
678	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
679	        if (!hasStructured && !hasFlat) {
680	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
681	                "an address must be supplied, either 'addressLine1' or 'address'");
682	        }
683	        if (hasStructured) {
684	            String line1 = normalizeAddress(owner.getAddressLine1());
685	            owner.setAddressLine1(line1);
686	            String composed = line1;
687	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
688	                String line2 = normalizeAddress(owner.getAddressLine2());
689	                owner.setAddressLine2(line2);
690	                composed = line1 + " " + line2;
691	            } else {
692	                owner.setAddressLine2(null);
693	            }
694	            owner.setAddress(composed);
695	        } else {
696	            owner.setAddressLine1(null);
697	            owner.setAddressLine2(null);
698	            owner.setAddress(normalizeAddress(owner.getAddress()));
699	        }
700	    }
701	
702	    /**
703	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
704	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
705	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
706	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
707	     *
708	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
709	     *
710	     * @param address the raw address supplied by the client, possibly {@code null}
711	     * @return the normalized address
712	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
713	     *                                 after normalization (required field)
714	     */
715	    private static String normalizeAddress(String address) {
716	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
717	        if (collapsed.isEmpty()) {
718	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
719	                "address must not be blank");
720	        }
721	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
722	        StringBuilder normalized = new StringBuilder();
723	        for (int i = 0; i < tokens.length; i++) {
724	            if (i > 0) {
725	                normalized.append(' ');
726	            }
727	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
728	        }
729	        return normalized.toString();
730	    }
731	
732	    /**
733	     * Determines whether the given whole identity key already belongs to any owner other than the
734	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
735	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
736	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
737	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
738	     *
739	     * @param identityKey the identity key to look for
740	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
741	     * @return {@code true} if another owner already has the same identity key
742	     */
743	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
744	        for (Owner existing : this.clinicService.findAllOwners()) {
745	            if (existing.isDeleted()) {
746	                continue;
747	            }
748	            if (excludeId != null && excludeId.equals(existing.getId())) {
749	                continue;
750	            }
751	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
752	                return true;
753	            }
754	        }
755	        return false;
756	    }
757	
758	    /**
759	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
760	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
761	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
762	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
763	     * this flags only the softer same-household-name overlap — in particular two owners with the same
764	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
765	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
766	     * deterministic when several owners qualify.
767	     *
768	     * @param owner the new owner being created, with its telephone already normalized
769	     * @return the matching existing owner, or {@code null} when none qualifies
770	     */
771	    private Owner findPossibleDuplicate(Owner owner) {
772	        if (owner.getLastName() == null || owner.getPostcode() == null) {
773	            return null;
774	        }
775	        String identityKey = ownerMapper.toIdentityKey(owner);
776	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
777	        return this.clinicService.findAllOwners().stream()
778	            .filter(existing -> !existing.isDeleted())
779	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
780	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
781	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
782	            .min(Comparator.comparingInt(Owner::getId))
783	            .orElse(null);
784	    }
785	
786	}
