163	        String code = owner.getCustomerCode();
164	        if (code == null) {
165	            return null;
166	        }
167	        int sum = 0;
168	        boolean dbl = true;
169	        for (int i = code.length() - 1; i >= 0; i--) {
170	            char c = code.charAt(i);
171	            if (c < '0' || c > '9') {
172	                continue;
173	            }
174	            int d = c - '0';
175	            if (dbl) {
176	                d *= 2;
177	                if (d > 9) {
178	                    d -= 9;
179	                }
180	            }
181	            sum += d;
182	            dbl = !dbl;
183	        }
